package com.smartblog.controller;
import com.smartblog.common.ApiResponse; import com.smartblog.dto.request.*; import com.smartblog.dto.response.*; import com.smartblog.service.*; import com.smartblog.util.*; import com.smartblog.vo.CurrentUser; import jakarta.servlet.http.HttpServletRequest; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/auth") public class AuthController { private final AuthService authService; private final EmailCodeService emailCodeService; private final SessionService sessionService; private final PasswordService passwordService; public AuthController(AuthService a,EmailCodeService e,SessionService s,PasswordService p){authService=a;emailCodeService=e;sessionService=s;passwordService=p;} @PostMapping("/email-code/send") public ApiResponse<EmailCodeResponse> sendRegisterEmailCode(@Valid @RequestBody EmailRequest request,HttpServletRequest servletRequest){return ApiResponse.success(emailCodeService.sendCode(AuthConstants.SCENE_REGISTER_EMAIL,request.email(),servletRequest));} @PostMapping("/register") public ApiResponse<Void> register(@Valid @RequestBody RegisterRequest request,HttpServletRequest servletRequest){authService.register(request,servletRequest); return ApiResponse.success("注册成功",null);} @PostMapping({"/login","/login/password"}) public ApiResponse<LoginResponse> login(@Valid @RequestBody LoginRequest request,HttpServletRequest servletRequest){return ApiResponse.success(authService.loginByPassword(request,servletRequest));} @PostMapping("/login/email-code/send") public ApiResponse<EmailCodeResponse> sendEmailLoginCode(@Valid @RequestBody EmailRequest request,HttpServletRequest servletRequest){return ApiResponse.success(emailCodeService.sendCode(AuthConstants.SCENE_LOGIN_EMAIL,request.email(),servletRequest));} @PostMapping("/login/email-code/verify") public ApiResponse<LoginResponse> emailCodeLogin(@Valid @RequestBody EmailCodeLoginRequest request,HttpServletRequest servletRequest){return ApiResponse.success(authService.loginByEmailCode(request,servletRequest));} @PostMapping("/token/refresh") public ApiResponse<LoginResponse> refresh(@Valid @RequestBody RefreshTokenRequest request){return ApiResponse.success(sessionService.refresh(request));} @PostMapping("/logout") public ApiResponse<Void> logout(HttpServletRequest request){sessionService.logoutCurrent(request); return ApiResponse.success("退出成功",null);} @PostMapping("/logout-all") public ApiResponse<Void> logoutAll(HttpServletRequest request){CurrentUser cu=UserContext.get(); sessionService.logoutAll(cu.userId(),request); return ApiResponse.success("已退出全部设备",null);} @PostMapping("/password/reset/request") public ApiResponse<EmailCodeResponse> resetRequest(@Valid @RequestBody PasswordResetRequest request,HttpServletRequest servletRequest){return ApiResponse.success(passwordService.requestReset(request,servletRequest));} @PostMapping("/password/reset/confirm") public ApiResponse<Void> resetConfirm(@Valid @RequestBody PasswordResetConfirmRequest request,HttpServletRequest servletRequest){passwordService.confirmReset(request,servletRequest); return ApiResponse.success("密码已重置，请重新登录",null);} @PostMapping("/password/change") public ApiResponse<Void> changePassword(@Valid @RequestBody PasswordChangeRequest request,HttpServletRequest servletRequest){CurrentUser cu=UserContext.get(); passwordService.changePassword(cu.userId(),request,servletRequest); return ApiResponse.success("密码修改成功，请重新登录",null);} @GetMapping("/sessions") public ApiResponse<List<SessionResponse>> sessions(){CurrentUser cu=UserContext.get(); return ApiResponse.success(sessionService.listSessions(cu.userId(),cu.sessionId()));} @DeleteMapping("/sessions/{sessionId}") public ApiResponse<Void> revokeSession(@PathVariable String sessionId){CurrentUser cu=UserContext.get(); sessionService.revokeSession(cu.userId(),sessionId); return ApiResponse.success("设备已下线",null);} }
